/**
 * Setup for Jest tests
 */

import '@testing-library/jest-dom';

// Mock fetch for testing
global.fetch = jest.fn();

// Mock missing DOM APIs that might be used in tests
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: jest.fn().mockImplementation(query => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: jest.fn(),
    removeListener: jest.fn(),
    addEventListener: jest.fn(),
    removeEventListener: jest.fn(),
    dispatchEvent: jest.fn(),
  })),
});

import '@testing-library/jest-dom';

jest.setTimeout(30000);

if (typeof global.TextEncoder === 'undefined') {
  const { TextEncoder } = require('util');
  global.TextEncoder = TextEncoder;
}

if (typeof global.TextDecoder === 'undefined') {
  const { TextDecoder } = require('util');
  global.TextDecoder = TextDecoder as unknown as typeof global.TextDecoder;
}

const fixedTestDate = new Date('2023-01-01T12:00:00Z');
jest
  .spyOn(global.Date, 'now')
  .mockImplementation(() => fixedTestDate.getTime());

afterEach(() => {
  jest.resetAllMocks();
});

expect.extend({
  toBeWithinRange(received, floor, ceiling) {
    const pass = received >= floor && received <= ceiling;
    if (pass) {
      return {
        message: () =>
          `expected ${received} not to be within range ${floor} - ${ceiling}`,
        pass: true,
      };
    }
    return {
      message: () =>
        `expected ${received} to be within range ${floor} - ${ceiling}`,
      pass: false,
    };
  },
});

declare global {
  namespace jest {
    interface Matchers<R> {
      toBeWithinRange(floor: number, ceiling: number): R;
    }
  }
}

import { RESOURCE_TYPE_CATALOG_ENTITY } from '@backstage/plugin-catalog-common/alpha';
import {
  infisicalPermissions,
  infisicalSecretCreatePermission,
  infisicalSecretDeletePermission,
  infisicalSecretDescribePermission,
  infisicalSecretUpdatePermission,
  infisicalSecretValueReadPermission,
} from './permissions';

describe('infisical permissions', () => {
  it.each([
    [infisicalSecretDescribePermission, 'infisical.secret.describe', 'read'],
    [
      infisicalSecretValueReadPermission,
      'infisical.secret.value.read',
      undefined,
    ],
    [infisicalSecretCreatePermission, 'infisical.secret.create', 'create'],
    [infisicalSecretUpdatePermission, 'infisical.secret.update', 'update'],
    [infisicalSecretDeletePermission, 'infisical.secret.delete', 'delete'],
  ])('%#: %s has the expected name and action', (permission, name, action) => {
    expect(permission.name).toBe(name);
    expect(permission.attributes.action).toBe(action);
    expect(permission.resourceType).toBe(RESOURCE_TYPE_CATALOG_ENTITY);
  });

  it('exposes all permissions in infisicalPermissions', () => {
    expect(infisicalPermissions.map(p => p.name)).toEqual([
      'infisical.secret.describe',
      'infisical.secret.value.read',
      'infisical.secret.create',
      'infisical.secret.update',
      'infisical.secret.delete',
    ]);
  });
});

/**
 * Mock implementation of InfisicalApi for testing
 */

import {
  InfisicalApi,
  GetEnvironmentsResponse,
  GetSecretsResponse,
} from './api/InfisicalClient';
import {
  InfisicalSecret,
  InfisicalSecretFormValues,
  InfisicalWorkspace,
} from './api/types';
import {
  mockWorkspaces,
  mockEnvironments,
  mockFolders,
  mockSecrets,
  createMockSecret,
} from './mocks';

/**
 * Creates a mock implementation of the InfisicalApi for testing
 *
 * @returns Mock InfisicalApi implementation
 */
export function createMockInfisicalApi(): InfisicalApi {
  // Create copies of the mock data to work with
  const workspaces = [...mockWorkspaces];
  const environments = [...mockEnvironments];
  const folders = [...mockFolders];
  let secrets = [...mockSecrets];

  return {
    getWorkspaces: async (): Promise<InfisicalWorkspace[]> => {
      return workspaces;
    },

    getEnvironments: async (
      entityRef: string,
    ): Promise<GetEnvironmentsResponse> => {
      if (!entityRef) {
        throw new Error('No entity reference provided');
      }

      return { environments };
    },

    getSecrets: async (
      entityRef: string,
      options?: { path?: string; environment?: string },
    ): Promise<GetSecretsResponse> => {
      if (!entityRef) {
        throw new Error('No entity reference provided');
      }

      // Filter folders based on path
      const filteredFolders = folders.filter(folder => {
        if (!options?.path) {
          // Root path - show top-level folders
          return folder.path.split('/').filter(Boolean).length === 1;
        }

        // Check if folder is a direct child of the current path
        const currentPathParts = options.path.split('/').filter(Boolean);
        const folderPathParts = folder.path.split('/').filter(Boolean);

        return (
          folderPathParts.length === currentPathParts.length + 1 &&
          folderPathParts.slice(0, currentPathParts.length).join('/') ===
            currentPathParts.join('/')
        );
      });

      // Filter secrets based on environment and path
      const filteredSecrets = secrets.filter(secret => {
        // No environment filtering
        if (options?.environment && secret.type !== options.environment) {
          return false;
        }

        // No path filtering for now
        return true;
      });

      // Mock a delay
      await new Promise(resolve => setTimeout(resolve, 500));

      return {
        secrets: filteredSecrets,
        folders: filteredFolders,
      };
    },

    createSecret: async (
      entityRef: string,
      secretData: InfisicalSecretFormValues
    ): Promise<InfisicalSecret> => {
      if (!entityRef) {
        throw new Error('No entity reference provided');
      }

      if (!secretData.secretValue) {
        throw new Error('Key and value are required fields');
      }

      const newSecret = [REDACTED]
        secretData.secretKey,
        secretData.secretValue,
        secretData.secretComment,
      );

      // Add to secrets array
      secrets = [...secrets, newSecret];

      // Mock a delay
      await new Promise(resolve => setTimeout(resolve, 500));

      return newSecret;
    },

    updateSecret: async (
      entityRef: string,
      secretId: string,
      secretData: InfisicalSecretFormValues
    ): Promise<InfisicalSecret> => {
      if (!entityRef) {
        throw new Error('No entity reference provided');
      }

      // Find the secret to update
      const secretIndex = secrets.findIndex(s => s.id === secretId);

      if (secretIndex === -1) {
        throw new Error(`Secret with ID ${secretId} not found`);
      }

      // Create updated secret; an omitted value keeps the current one
      const current = secrets[secretIndex];
      const value = secretData.secretValue ?? current.secretValue;
      const updatedSecret = {
        ...current,
        key: secretData.secretKey,
        secretKey: secretData.secretKey,
        value,
        secretValue: value,
        comment: secretData.secretComment,
        secretComment: secretData.secretComment,
        updatedAt: new Date().toISOString(),
      };

      // Update the secret
      secrets = [
        ...secrets.slice(0, secretIndex),
        updatedSecret,
        ...secrets.slice(secretIndex + 1),
      ];

      // Mock a delay
      await new Promise(resolve => setTimeout(resolve, 500));

      return updatedSecret;
    },

    deleteSecret: async (
      entityRef: string,
      secretId: string
    ): Promise<void> => {
      if (!entityRef) {
        throw new Error('No entity reference provided');
      }

      // Remove the secret
      secrets = secrets.filter(s => s.id !== secretId);

      // Mock a delay
      await new Promise(resolve => setTimeout(resolve, 500));
    },

    getSecretByKey: async (
      entityRef: string,
      secretKey: string
    ): Promise<InfisicalSecret> => {
      if (!entityRef) {
        throw new Error('No entity reference provided');
      }

      // Find the secret by key
      const secret = [REDACTED] => s.key === secretKey);

      // Mock a delay
      await new Promise(resolve => setTimeout(resolve, 500));

      if (!secret) {
        throw new Error('Secret not found');
      }

      return secret;
    },
  };
}

/**
 * Tests for SearchBar component
 */

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { SearchBar } from './SearchBar';

describe('SearchBar', () => {
    const mockOnSearchChange = jest.fn();

    beforeEach(() => {
        jest.clearAllMocks();
    });

    it('renders correctly with empty search text', () => {
        render(
            <SearchBar
                searchText=""
                onSearchChange={mockOnSearchChange}
            />
        );

        expect(screen.getByPlaceholderText('Filter')).toBeInTheDocument();
        // Clear icon should not be visible when search text is empty
        expect(screen.queryByRole('button')).not.toBeInTheDocument();
    });

    it('renders correctly with search text', () => {
        render(
            <SearchBar
                searchText="api"
                onSearchChange={mockOnSearchChange}
            />
        );

        const inputElement = screen.getByPlaceholderText('Filter');
        expect(inputElement).toBeInTheDocument();
        expect(inputElement).toHaveValue('api');

        // Clear icon should be visible when search text is not empty
        expect(screen.getByRole('button')).toBeInTheDocument();
    });

    it('calls onSearchChange when input value changes', () => {
        render(
            <SearchBar
                searchText=""
                onSearchChange={mockOnSearchChange}
            />
        );

        const inputElement = screen.getByPlaceholderText('Filter');
        fireEvent.change(inputElement, { target: { value: 'test' } });

        expect(mockOnSearchChange).toHaveBeenCalledWith('test');
    });

    it('clears search text when clear button is clicked', () => {
        render(
            <SearchBar
                searchText="api"
                onSearchChange={mockOnSearchChange}
            />
        );

        const clearButton = screen.getByRole('button');
        fireEvent.click(clearButton);

        expect(mockOnSearchChange).toHaveBeenCalledWith('');
    });
});

import { ConfigReader } from '@backstage/config';
import { mockServices } from '@backstage/backend-test-utils';
import { InfisicalApiClient, buildUserAgent } from '../InfisicalApi';
import { InputError } from '@backstage/errors';

global.fetch = jest.fn();

/** A successful JSON response as returned by the mocked fetch */
function jsonResponse(body: unknown) {
  return {
    ok: true,
    status: 200,
    json: () => Promise.resolve(body),
    text: () => Promise.resolve(JSON.stringify(body)),
    headers: { get: () => 'application/json' },
  };
}

/** A failed JSON response as returned by the mocked fetch */
function errorResponse(status: number, message = 'nope') {
  const body = { statusCode: status, message };
  return {
    ok: false,
    status,
    json: () => Promise.resolve(body),
    text: () => Promise.resolve(JSON.stringify(body)),
    headers: { get: () => 'application/json' },
  };
}

describe('InfisicalApiClient', () => {
  const mockConfig = new ConfigReader({
    infisical: {
      baseUrl: 'https://test-api.example.com',
      authentication: {
        auth_token: {
          token: '[REDACTED]',
        },
      },
    },
  });

  const mockClientCredentialsConfig = new ConfigReader({
    infisical: {
      baseUrl: 'https://test-api.example.com',
      authentication: {
        universalAuth: {
            clientId: 'test-client-id',
            clientSecret: '[REDACTED]',
        }
      },
    },
  });

  const logger = mockServices.rootLogger();
  let apiClient: InfisicalApiClient;

  beforeEach(() => {
    jest.resetAllMocks();
  });

  describe('constructor', () => {
    it('should initialize with API token authentication', () => {
      apiClient = new InfisicalApiClient({ config: mockConfig, logger });
      expect(apiClient).toBeDefined();
    });

    it('should initialize with client credentials authentication', () => {
      apiClient = new InfisicalApiClient({
        config: mockClientCredentialsConfig,
        logger,
      });
      expect(apiClient).toBeDefined();
    });

    it('should throw error if no authentication is provided', () => {
      const invalidConfig = new ConfigReader({
        infisical: {
          baseUrl: 'https://test-api.example.com',
        },
      });
      let error: Error | null = null;
      try {
        // eslint-disable-next-line no-new
        new InfisicalApiClient({
          config: invalidConfig,
          logger,
        });
      } catch (err) {
        error = err as Error;
      }

      expect(error).toBeInstanceOf(Error);
      expect(error?.message).toContain(
        'Missing Infisical Authentication credentials',
      );
    });
  });

  describe('getSecrets', () => {
    beforeEach(() => {
      apiClient = new InfisicalApiClient({ config: mockConfig, logger });
    });

    it('should fetch secrets and folders successfully', async () => {
      // Both requests run in parallel, so answer by URL rather than call order
      (global.fetch as jest.Mock).mockImplementation((url: string) =>
        Promise.resolve(
          jsonResponse(
            new URL(url).pathname === '/api/v1/folders'
              ? { folders: [{ id: 'folder-1', name: 'nested' }] }
              : {
                  secrets: [
                    {
                      id: 'mock-secret-1',
                      key: 'API_KEY',
                      value: 'mock-value-1',
                    },
                    {
                      id: 'mock-secret-2',
                      key: 'DATABASE_URL',
                      value: 'mock-value-2',
                    },
                  ],
                },
          ),
        ),
      );

      const result = await apiClient.getSecrets('workspace123', '/path', 'dev');

      expect(global.fetch).toHaveBeenCalledTimes(2);
      expect(result.secrets).toHaveLength(2);
      expect(result.secrets[0].key).toBe('API_KEY');
      expect(result.folders).toEqual([{ id: 'folder-1', name: 'nested' }]);
    });

    it('maps a plain text error without retrying', async () => {
      (global.fetch as jest.Mock).mockResolvedValue({
        ok: false,
        status: 404,
        headers: { get: () => 'text/plain' },
        text: () => Promise.resolve('Resource not found'),
        json: () => Promise.reject(new Error('Not JSON')),
      });

      await expect(
        apiClient.getSecrets('workspace123', '/path', 'dev'),
      ).rejects.toMatchObject({
        name: 'NotFoundError',
        message: 'Infisical API error (404): Resource not found',
      });
      // One call for the secrets and one for the folders
      expect(global.fetch).toHaveBeenCalledTimes(2);
    });
  });

  describe('error mapping and retries', () => {
    const secretData = {
      secretKey: 'KEY',
      secretValue: 'value',
      secretPath: '/',
      workspaceId: 'workspace123',
      environment: 'dev',
    };
    const fetchMock = global.fetch as jest.Mock;

    beforeEach(() => {
      apiClient = new InfisicalApiClient({ config: mockConfig, logger });
      (apiClient as any).retryDelay = 0;
    });

    it.each([
      [400, 'InputError'],
      [422, 'InputError'],
      [403, 'NotAllowedError'],
      [404, 'NotFoundError'],
      [409, 'ConflictError'],
      [401, 'Error'],
    ])('maps a JSON %i to %s without retrying', async (status, name) => {
      fetchMock.mockResolvedValue(
        errorResponse(status, 'identity not in project'),
      );

      await expect(
        apiClient.getEnvironments('workspace123'),
      ).rejects.toMatchObject({
        name,
        message: `Infisical API error (${status}): identity not in project`,
      });
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('marks a 403 from Infisical so it is not mistaken for a missing permission', async () => {
      fetchMock.mockResolvedValue(errorResponse(403, 'not a project member'));

      await expect(
        apiClient.getEnvironments('workspace123'),
      ).rejects.toMatchObject({
        name: 'NotAllowedError',
        reason: 'infisical-forbidden',
      });
    });

    it('retries a read on 5xx and then fails with ServiceUnavailableError', async () => {
      fetchMock.mockResolvedValue(errorResponse(500));

      await expect(
        apiClient.getEnvironments('workspace123'),
      ).rejects.toMatchObject({ name: 'ServiceUnavailableError' });
      // The first attempt plus three retries
      expect(fetchMock).toHaveBeenCalledTimes(4);
    });

    it('returns the result when a retried read succeeds', async () => {
      fetchMock
        .mockResolvedValueOnce(errorResponse(503))
        .mockResolvedValueOnce(
          jsonResponse({ workspace: { id: 'w', environments: [] } }),
        );

      await expect(
        apiClient.getEnvironments('workspace123'),
      ).resolves.toMatchObject({ id: 'w' });
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    it('retries a read on a network error', async () => {
      fetchMock
        .mockRejectedValueOnce(new TypeError('fetch failed'))
        .mockResolvedValueOnce(
          jsonResponse({ workspace: { id: 'w', environments: [] } }),
        );

      await expect(
        apiClient.getEnvironments('workspace123'),
      ).resolves.toMatchObject({ id: 'w' });
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    it('retries a read when the connection drops while reading the body', async () => {
      fetchMock
        .mockResolvedValueOnce({
          ...jsonResponse({}),
          json: () => Promise.reject(new TypeError('terminated')),
        })
        .mockResolvedValueOnce(
          jsonResponse({ workspace: { id: 'w', environments: [] } }),
        );

      await expect(
        apiClient.getEnvironments('workspace123'),
      ).resolves.toMatchObject({ id: 'w' });
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    it('does not retry a write when reading the body fails', async () => {
      fetchMock.mockResolvedValue({
        ...jsonResponse({}),
        json: () => Promise.reject(new TypeError('terminated')),
      });

      await expect(apiClient.createSecret(secretData)).rejects.toThrow(
        'terminated',
      );
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('does not retry a write on a network error', async () => {
      fetchMock.mockRejectedValue(new TypeError('fetch failed'));

      await expect(apiClient.createSecret(secretData)).rejects.toThrow(
        'fetch failed',
      );
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it.each([500, 503, 403])('does not retry a write on %i', async status => {
      fetchMock.mockResolvedValue(errorResponse(status));

      await expect(apiClient.createSecret(secretData)).rejects.toBeDefined();
      await expect(
        apiClient.updateSecret(secretData, 'KEY'),
      ).rejects.toBeDefined();
      await expect(
        apiClient.deleteSecret('KEY', secretData),
      ).rejects.toBeDefined();
      expect(fetchMock).toHaveBeenCalledTimes(3);
    });

    it('retries a write when rate limited', async () => {
      fetchMock
        .mockResolvedValueOnce(errorResponse(429))
        .mockResolvedValueOnce(jsonResponse({ secret: { secretKey: 'KEY' } }));

      await expect(apiClient.createSecret(secretData)).resolves.toMatchObject({
        secretKey: 'KEY',
      });
      expect(fetchMock).toHaveBeenCalledTimes(2);
    });

    describe('with universal auth', () => {
      const loginResponse = jsonResponse({
        accessToken: 'token',
        expiresIn: 3600,
      });
      const isLogin = (call: unknown[]) =>
        String(call[0]).endsWith('/v1/auth/universal-auth/login');

      beforeEach(() => {
        apiClient = new InfisicalApiClient({
          config: mockClientCredentialsConfig,
          logger,
        });
        (apiClient as any).retryDelay = 0;
      });

      it('logs in again once on 401 and then gives up', async () => {
        fetchMock.mockImplementation(async (url: string) =>
          url.endsWith('/login') ? loginResponse : errorResponse(401),
        );

        await expect(apiClient.getEnvironments('workspace123')).rejects.toThrow(
          'Infisical API error (401)',
        );

        const calls = fetchMock.mock.calls;
        expect(calls.filter(isLogin)).toHaveLength(2);
        expect(calls.filter(call => !isLogin(call))).toHaveLength(2);
      });

      describe('token expiry margin', () => {
        const NOW = 1_700_000_000_000;
        let now: jest.SpyInstance;

        // Logs in with a token that lives `expiresIn` seconds, makes a
        // request, moves the clock and makes another one
        async function loginsAfter(expiresIn: number, elapsedSeconds: number) {
          fetchMock.mockImplementation(async (url: string) =>
            url.endsWith('/login')
              ? jsonResponse({ accessToken: 'token', expiresIn })
              : jsonResponse({ workspace: { environments: [] } }),
          );

          await apiClient.getEnvironments('workspace123');
          now.mockReturnValue(NOW + elapsedSeconds * 1000);
          await apiClient.getEnvironments('workspace123');

          return fetchMock.mock.calls.filter(isLogin).length;
        }

        beforeEach(() => {
          // setupTests stubs Date.now, but resetAllMocks clears that stub
          // between tests
          now = jest.spyOn(Date, 'now').mockReturnValue(NOW);
        });

        it('refreshes a long-lived token 5 minutes before it expires', async () => {
          await expect(loginsAfter(3600, 3299)).resolves.toBe(1);
        });

        it('logs in again once the 5 minute margin is reached', async () => {
          await expect(loginsAfter(3600, 3300)).resolves.toBe(2);
        });

        it.each([
          [300, 239],
          [60, 47],
        ])(
          'reuses a token that lives %i seconds for 80%% of its lifetime',
          async (expiresIn, elapsedSeconds) => {
            await expect(loginsAfter(expiresIn, elapsedSeconds)).resolves.toBe(
              1,
            );
          },
        );

        it.each([
          [300, 240],
          [60, 48],
        ])(
          'logs in again when a token that lives %i seconds is 80%% through',
          async (expiresIn, elapsedSeconds) => {
            await expect(loginsAfter(expiresIn, elapsedSeconds)).resolves.toBe(
              2,
            );
          },
        );
      });

      it('does not retry a failed login', async () => {
        fetchMock.mockResolvedValue({
          ...errorResponse(401),
          text: () => Promise.resolve('Invalid credentials'),
        });

        await expect(apiClient.getEnvironments('workspace123')).rejects.toThrow(
          'Failed to authenticate: 401',
        );
        expect(fetchMock).toHaveBeenCalledTimes(1);
      });
    });
  });

  describe('URL path segments', () => {
    beforeEach(() => {
      apiClient = new InfisicalApiClient({ config: mockConfig, logger });
      (global.fetch as jest.Mock).mockResolvedValue(
        jsonResponse({ secret: { id: 'id', key: 'key', value: 'value' } }),
      );
    });

    function requestedUrl(): URL {
      return new URL((global.fetch as jest.Mock).mock.calls[0][0]);
    }

    it('encodes slashes and query characters in the secret key', async () => {
      await apiClient.getSecretById(
        'workspace123',
        '../../../v1/workspace/other?workspaceId=other&x=',
        { environment: 'dev', path: '/api' },
      );

      const url = requestedUrl();
      expect(url.pathname).toBe(
        '/api/v3/secrets/raw/..%2F..%2F..%2Fv1%2Fworkspace%2Fother%3FworkspaceId%3Dother%26x%3D',
      );
      expect(url.searchParams.getAll('workspaceId')).toEqual(['workspace123']);
    });

    it('encodes the key of a new secret', async () => {
      await apiClient.createSecret({
        secretKey: 'a/b',
        secretValue: 'v',
        workspaceId: 'workspace123',
        secretPath: '/',
        environment: 'dev',
      });

      expect(requestedUrl().pathname).toBe('/api/v3/secrets/raw/a%2Fb');
    });

    it('encodes the workspace ID', async () => {
      (global.fetch as jest.Mock).mockResolvedValue(
        jsonResponse({ workspace: { id: 'w', environments: [] } }),
      );

      await apiClient.getEnvironments('../secrets/raw');

      expect(requestedUrl().pathname).toBe(
        '/api/v1/workspace/..%2Fsecrets%2Fraw',
      );
    });

    it.each(['.', '..', ''])(
      'rejects the dot segment %j without calling Infisical',
      async secretId => {
        await expect(
          apiClient.deleteSecret(secretId, {
            workspaceId: 'workspace123',
            secretPath: '/',
            environment: 'dev',
          }),
        ).rejects.toThrow(InputError);
        await expect(
          apiClient.updateSecret(
            {
              secretKey: 'KEY',
              secretValue: 'v',
              workspaceId: 'workspace123',
              secretPath: '/',
              environment: 'dev',
            },
            secretId,
          ),
        ).rejects.toThrow(InputError);
        expect(global.fetch).not.toHaveBeenCalled();
      },
    );
  });

  describe('client credentials authentication', () => {
    beforeEach(() => {
      apiClient = new InfisicalApiClient({
        config: mockClientCredentialsConfig,
        logger,
      });

      (apiClient as any).authenticateWithClientCredentials = jest
        .fn()
        .mockResolvedValue(undefined);
    });

    it('should authenticate and get a token', async () => {
      (global.fetch as jest.Mock).mockImplementationOnce(() =>
        Promise.resolve({
          ok: true,
          status: 200,
          json: () =>
            Promise.resolve({
              workspace: {
                id: 'workspace-1',
                name: 'Test Project',
                slug: 'test-project',
                environments: [
                  { id: 'env-1', name: 'Development', slug: 'dev' },
                  { id: 'env-2', name: 'Production', slug: 'prod' },
                ],
              },
            }),
          text: () =>
            Promise.resolve(
              JSON.stringify({
                workspace: {
                  id: 'workspace-1',
                  name: 'Test Project',
                  slug: 'test-project',
                  environments: [
